  static void NetworkResponsiveness(string game,string user,string data){
   var type=typeof(ModernController);var signature=new[]{typeof(string),typeof(string),typeof(string),typeof(bool),typeof(Func<Engine,ulong[],Action<int,string>,CancellationToken,bool,Dictionary<ulong,string>>),typeof(Func<Engine,string,Dictionary<string,object>,Action<int,string>,CancellationToken,Action<object>,object>)};
   var ctor=type.GetConstructor(BindingFlags.Instance|BindingFlags.NonPublic,null,signature,null);Assert(ctor!=null,"network reads have a distinct guarded execution lane");
   using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim()){
    Func<Engine,string,Dictionary<string,object>,Action<int,string>,CancellationToken,Action<object>,object> fetch=(e,a,p,progress,token,batch)=>{entered.Set();progress(-1,"synthetic network pending");batch(new{servers=new[]{new{id="hall:1",name="first"}}});WaitHandle.WaitAny(new[]{release.WaitHandle,token.WaitHandle});token.ThrowIfCancellationRequested();return new{servers=new object[0]};};
    using(var c=(ModernController)ctor.Invoke(new object[]{game,user,data,true,null,fetch})){
     Exception networkError=null;var thread=new Thread(()=>{try{c.Execute("serverHall",new Dictionary<string,object>{{"requestId","test-hall-1"},{"query",""}});}catch(Exception x){networkError=x;}});thread.Start();Assert(entered.Wait(5000),"slow hall request entered independent lane");
     var local=System.Threading.Tasks.Task.Run(()=>{Call(c,"theme",new Dictionary<string,object>{{"value","light"}});return D(Call(c,"status"));});
     Assert(local.Wait(1500)&&Convert.ToString(local.Result["theme"])=="light","local mutation and status do not wait for slow hall");
     Reject(()=>Call(c,"setGame",new Dictionary<string,object>{{"path",game}}),"directory change cannot invalidate a live network engine");
     foreach(string action in new[]{"buddyTakeover","buddyRecover"})Reject(()=>Call(c,action,new Dictionary<string,object>{{"stamp","opaque"},{"confirmed",true},{"steamExitConfirmed",true}}),"takeover cannot exit underneath outstanding network work: "+action);Assert(c.NetworkBusy&&!thread.Join(100),"takeover refusal leaves Steam request alive until explicit cancellation");
     Reject(()=>Call(c,"launch"),"synthetic launch still forbids real game startup");Assert(thread.Join(1500)&&networkError is OperationCanceledException,"launch releases pending Steam identity before startup path");
     Assert(D(Call(c,"status")).ContainsKey("gamePath"),"network cancellation leaves local actions usable");
    }
   }
   HallReceiptOrdering(game,user,Path.Combine(data,"Ordering"));
  }
  static void HallReceiptOrdering(string game,string user,string data){
   var reserve=typeof(ModernController).GetMethod("ReserveHall");Assert(reserve!=null,"hall receipt reserves generation before asynchronous scheduling");
   using(var entered=new ManualResetEventSlim())using(var release=new ManualResetEventSlim()){
    string receivedId=null,progressId=null;int calls=0;
    Func<Engine,string,Dictionary<string,object>,Action<int,string>,CancellationToken,Action<object>,object> fetch=(e,a,p,progress,token,batch)=>{Interlocked.Increment(ref calls);progress(-1,"pending");batch(new{servers=new[]{new{id="hall:1"}}});entered.Set();WaitHandle.WaitAny(new[]{release.WaitHandle,token.WaitHandle});token.ThrowIfCancellationRequested();return new{servers=new object[0]};};
    using(var c=new ModernController(game,user,data,true,null,fetch)){
     c.Event=(name,value)=>{var dto=D(value);if(name=="hallBatch")receivedId=Convert.ToString(dto["requestId"]);if(name=="networkProgress")progressId=Convert.ToString(dto["requestId"]);};
     var older=new Dictionary<string,object>{{"requestId","older"}};var newer=new Dictionary<string,object>{{"requestId","newer"}};reserve.Invoke(c,new object[]{older});reserve.Invoke(c,new object[]{newer});
     Exception failure=null;var latest=new Thread(()=>{try{c.Execute("serverHall",newer);}catch(Exception ex){failure=ex;}});latest.Start();Assert(entered.Wait(5000),"latest reserved hall request starts");
     Reject(()=>c.Execute("serverHall",older),"late scheduling of an older hall cannot supersede latest receipt");
     c.Execute("cancel",new Dictionary<string,object>{{"scope","hall"},{"requestId","older"}});Assert(calls==1&&!latest.Join(100),"late cancel of an older hall leaves newest query alive");
     Assert(receivedId=="newer"&&progressId=="newer","batch and progress retain exact originating request identity");
     c.Execute("cancel",new Dictionary<string,object>{{"scope","hall"},{"requestId","newer"}});Assert(latest.Join(5000)&&failure is OperationCanceledException,"matching hall cancel drains current query");
    }
   }
  }
